<div class="head"><div><h1><?= icon('card') ?> Payment Records</h1><p class="muted">Confirm customer-submitted payments, correct details and review every transaction.</p></div></div>
<form method="get" class="filter wrap"><input type="hidden" name="r" value="payments/index"><input name="q" placeholder="Customer, meter or reference" value="<?= e($f['q']) ?>" aria-label="Search">
<select name="status" aria-label="Status"><option value="">All statuses</option><?php foreach (['Pending', 'Completed', 'Rejected', 'Voided'] as $s): ?><option <?= $f['status'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select>
<select name="method" aria-label="Method"><option value="">All methods</option><?php foreach (['Cash', 'Mobile Money', 'Bank Transfer', 'Card'] as $m): ?><option <?= $f['method'] === $m ? 'selected' : '' ?>><?= $m ?></option><?php endforeach; ?></select>
<label for="pf">From</label><input id="pf" type="date" name="from" value="<?= e($f['from']) ?>"><label for="pt">To</label><input id="pt" type="date" name="to" value="<?= e($f['to']) ?>"><button class="btn sm">Filter</button><?php if (array_filter($f)): ?><?= act_link('warn', 'Clear', url('payments/index')) ?><?php endif; ?></form>
<div class="panel"><div class="tw"><table><tr><th>Date</th><th>Customer</th><th>Bill</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Actions</th></tr>
<?php $sum = 0; foreach ($rows as $p): if ($p['status'] === 'Completed') $sum += (float)$p['amount_paid']; ?><tr><td><?= e($p['payment_date']) ?></td><td><?= e($p['full_name']) ?> <small class="muted"><?= e($p['meter_no']) ?></small></td><td><?= e($p['billing_month']) ?></td><td><?= e(money($p['amount_paid'])) ?></td><td><?= e($p['payment_method']) ?></td><td><?= e($p['transaction_reference']) ?></td><td><?= badge($p['status']) ?></td>
<td class="acts2"><?php if ($p['status'] === 'Pending'): ?><?= act_form('ok', 'Confirm', 'payments/confirm', ['payment_id' => $p['payment_id']]) ?><?= act_form('del', 'Reject', 'payments/reject', ['payment_id' => $p['payment_id']], 'Reject this payment?') ?>
<?php elseif ($p['status'] === 'Completed' && $u['role'] === 'admin'): ?><?= act_link('edit', 'Edit', url('payments/edit', ['id' => $p['payment_id']])) ?><?= act_form('warn', 'Void', 'payments/void', ['payment_id' => $p['payment_id']], 'Void this payment? The bill balance will be recalculated.') ?><?php endif; ?><?= act_link('view', 'Bill', url('bills/show', ['id' => $p['bill_id']])) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="muted">No payments found.</td></tr><?php endif; ?></table></div><p class="muted">Completed total in this list: <b><?= e(money($sum)) ?></b></p></div>
